import re,hashlib,json
from pathlib import Path
root=Path("/home/jonny/projects/boardgame-rules/docs/quality/summary-qa/john-company-second-edition/2026-11-05-batch-002957/expanded-v13-complete-requested-scope/luna-iteration-01")
s=(root/"summary-snapshot.md").read_text(); hs=list(re.finditer(r"(?m)^(#{1,6}) (.+)$",s)); i=next(i for i,h in enumerate(hs) if h.group(2).startswith("III. Hiring")); h=hs[i]; e=hs[i+1].start(); t=s[h.start():e]; st=s[:h.start()].count("\n")+1; sid="I"+str(st).zfill(3)
md={"section_id":sid,"kind":"introduction","heading":h.group(),"level":len(h.group(1)),"start_offset":h.start(),"end_offset":e,"start_line":st,"end_line":st+t.count("\n")-(1 if t.endswith("\n") else 0),"sha256":hashlib.sha256(t.encode()).hexdigest()}
