led=[("How is a Chairman elected","Former Chairman first announces the number of shares needed for a pure majority (more than half of current shares). Any shareholder may campaign; first candidate supported by players controlling that many shares wins."),("how does a deadlocked election resolve","If no candidate gets support, former Chairman picks any shareholder including self; no Nepotism consent."),("does the elected Chairman piece remain a tradable Company share","It still counts as a share for dividends, majority and scoring, but cannot be traded or invested in firms.")]
entry={"id":q["id"],"clause_ledger":[{"requested_clause":a,"section_ids":[sid],"fact_kind":"quote","fact_source_section":sid,"supported_fact_or_case_result":b} for a,b in led],"case_conclusions":[],"operative_sections":[md],"answer":"Applicable summary text\n\n"+block,"support":"supported","evidence":[{"summary_location":sid,"quote":h.group()}]}
old["answers"].append(entry); (root/"reader-a-draft.json").write_text(json.dumps(old,ensure_ascii=False,indent=2)+"\n")
PY","max_output_tokens":1000});
text(r.output);

